insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-state-university'), NULL, NULL, 'claim', 'FSU requires agents to register with FSU (online Agent Registration Form) before contacting an athlete about NIL.');
