insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'claim', 'Canes Connection is the official NIL collective of Miami Athletics (2023 release, restated July 1, 2025).');
