insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'ambiguity', 'Sports with no gender label in the staff directory (Golf, Rowing, Swimming & Diving, Track & Field/Cross Country) were left out of the sports lists.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-miami'), NULL, NULL, 'conflict', 'The Miami NIL Policy page says university-linked entities may not pay athletes for NIL. The July 1, 2025 AD letter says athletics departments can now share revenue directly. The policy page has not been updated.');
