insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'claim', 'USF''s compliance page has no NIL content.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'ambiguity', 'The 2022 guidelines page is pre-House. It says: USF, the athletic department, staff or boosters may not pay or arrange NIL pay; USF marks, logos, green and gold colors, team photos and video and all parts of the uniform need written agreement or permission from the University (it names Kim Hill, USF''s Chief Marketing Officer); athletes may not sell or sign USF-issued gear; no NIL deals with gambling or sports wagering vendors or vendors tied to performance enhancing drugs; contracts may not run past participation at USF; agents must be licensed in Florida. None of this is treated as current.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'ambiguity', 'The 2022 page names Kim Hill as the person who grants written permission for marks. This was not confirmed as current.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'ambiguity', 'Page dates for USF sources were taken from the URLs.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'ambiguity', 'Street address and sports list were not read on an official page and are left empty.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'ambiguity', 'No USF statement on the status of any collective was found. The closure of the Fowler Avenue Collective comes from news reporting.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'ambiguity', 'The Bulls Athletic Properties release calls it an ''independent division''. Its exact legal form is not stated.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'university-of-south-florida'), NULL, NULL, 'conflict', 'Inside the 2022 guidelines page: the rules text says athletes must disclose ''within four days'' and the FAQ says ''Within five days of NIL agreement through the INFLCR App.''');
