insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'claim', 'FAU requires prior express written permission to use FAU, conference or NCAA marks or facilities in NIL, and says the going rate is paid.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'claim', 'FAU tells international students to contact the International Student Services Office before any NIL activity.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'claim', 'FAU staff may seek and connect NIL opportunities for current athletes (handbook list ''FAU Institutional Staff Members MAY'').');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'claim', 'The Opendorse Owls Marketplace is the marketplace FAU links to in 2025 and 2026.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'claim', '''NIL in Paradise is the official collective'' comes from a 2024 page. Current status is not confirmed.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'The handbook does not name the disclosure platform. The handbook separately mentions Opendorse as a personal branding tool and Teamworks for employment forms, but neither is called the NIL disclosure platform.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'Two live FAU pages disagree on collectives. The 2021-URL page lists Paradise Collective, Owl Collective and Prowlerz Club. The 2024 page names NIL in Paradise as the official collective. Both are dated before July 2025.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'The Agents page (2023) tells agents to send registrations to John Stephenson, who is not on the current compliance staff list. The current compliance lead listed is Garrett Franskousky.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'The 2024-25 handbook had a list ''FAU Institutional Staff Members MAY NOT'' (promise NIL in recruiting, donate to NIL entities). That list is not in the 2026-27 handbook.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'FAU''s pages say the settlement ''opens the door for revenue sharing'' but no FAU page read states that FAU pays revenue share or how much. No school-payments rule is recorded.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'Compliance staff phone numbers and the street address come from a WebFetch summary of the staff directory, not raw text.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'The site navigation has one Swimming and Diving link. It is listed under both men and women here and should be checked. The compliance page still names AAC, CUSA and ASUN.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'Handbook quotes were cleaned of stray spaces added by PDF text extraction (for example ''Student - athletes'').');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-atlantic-university'), NULL, NULL, 'ambiguity', 'TheLinkU (2023) status at FAU is not confirmed.');
