insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'claim', 'FIU facilities must be arranged and approved through FIU Athletics, with rental rates.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'ambiguity', 'Policy 910.001 was last revised May 8, 2023, before the House settlement. The 2026-2027 handbook repeats its text, so it is treated as current.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'ambiguity', 'Procedure 910.001a is ''temporarily rescinded'' in the policy PDF, yet the 2026-2027 handbook still lists procedure steps (INFLCR app, approval request form, 10 days to resolve conflicts).');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'ambiguity', 'The handbook sentence on review timing is garbled: ''All transactions will be reviewed by the Sr. Associate Athletic Director shall be given within five (5) business days of receipt of the Name, Image and Likeness Approval Request form.''');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'ambiguity', 'The handbook''s NIL Go text includes old dates (deals before June 7, 2025 reported by July 1, 2025). It restates the national process and is not recorded as an FIU rule.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'ambiguity', 'The Panther Exchange (2023), The Blueprint Collective (2023) and ROAR (2021) come from pre-July 2025 releases. Current status is not confirmed. fiusports.com/exchange still redirects to INFLCR.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'florida-international-university'), NULL, NULL, 'ambiguity', 'The Panther Club page says FIU and other Division I schools ''are able to offer increased benefits to student-athletes through revenue sharing'' as of July 1, 2025. It does not say whether or how much FIU pays. No school-payments rule is recorded.');
