insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'jacksonville-university'), NULL, NULL, 'ambiguity', 'The JU NIL page is dated May 9, 2022 by its URL. It cites Florida Statute 1006.74 and May 10, 2022 NCAA guidance, both from before the House settlement. It is still the NIL page linked in the Compliance menu.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'jacksonville-university'), NULL, NULL, 'ambiguity', 'The page says ''Neither JU nor JU staff members may compensate or arrange compensation'' for NIL and that staff ''cannot facilitate NIL conversations or arrangements''. These lines reflect pre-House rules and are not recorded as current rules.');
