insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'jacksonville-university'), NULL, NULL, 'ambiguity', 'The NIL page lists Daniel Calderon as Compliance Coordinator. The staff directory lists him as Director of Compliance. The directory title is used.');
