insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'winter-park-high-school-winter-park'), NULL, NULL, 'left_off_page', 'Winter Park''s athletics site has a menu item called NIL. It opens a copy of FHSAA Form GA1 (Affidavit of Amateurism). The site adds no NIL rules of its own. Reason: Recorded as a disclosure note instead (the NIL menu item opens Form GA1).');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'winter-park-high-school-winter-park'), NULL, NULL, 'left_off_page', 'Winter Park''s eligibility page says an athlete must be an amateur and must not accept money, gifts or donations for participating in a sport. Reason: An undated eligibility line that says athletes may not accept money for playing. It predates or ignores the FHSAA NIL rule, so it is not shown as the school''s position.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'winter-park-high-school-winter-park'), NULL, NULL, 'claim', 'The athletics site has a menu item labelled ''NIL'' that links to GA1_Affidavit_of_Amateurism_81624-1.pdf.');
insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'winter-park-high-school-winter-park'), NULL, NULL, 'claim', 'The eligibility page says athletes must not accept money, gifts or donations for participating in a sport, citing FHSAA Bylaw 9.9.');
