insert into school_review_notes (institution_id, district_id, governing_body_id, kind, body) values ((select id from institutions where slug = 'winter-park-high-school-winter-park'), NULL, NULL, 'ambiguity', 'The eligibility page is undated and its amateur wording does not mention the NIL exception. It should not be shown as the school''s full position on NIL.');
